/* Synonym Trainer bank: 154 sets, B2-C1. Each item has a part of speech and an example; each set has a usage note. 'grp' = meaning family (never mixed as intruders). */
window.SYN_SETS=[{"id":"cn-cause-noun","cat":"connector","grp":"cause","topic":"Cause and effect","level":"B2","note":"All four are followed by a NOUN or noun phrase, not a clause. 'Thanks to' usually gives a positive or neutral cause; 'owing to' and 'due to' are more formal, and 'due to' often follows the verb 'be' (The delay was due to...).","items":[{"t":"because of","pos":"prep","ex":"The match was cancelled because of heavy rain."},{"t":"due to","pos":"prep","ex":"The delay was due to a signal failure."},{"t":"owing to","pos":"prep","ex":"Owing to staff shortages, the library closed early."},{"t":"thanks to","pos":"prep","ex":"Thanks to the new vaccine, deaths fell sharply."}]},{"id":"cn-cause-clause","cat":"connector","grp":"cause","topic":"Cause and effect","level":"B2","note":"These are followed by a CLAUSE (subject + verb). 'Since' and 'as' usually start the sentence and give a reason the reader already knows; 'because' answers the question 'why?' directly.","items":[{"t":"because","pos":"conj","ex":"Many students fail because they leave revision too late."},{"t":"since","pos":"conj","ex":"Since public transport is cheap, more people use it."},{"t":"as","pos":"conj","ex":"As the population is ageing, healthcare costs are rising."}]},{"id":"cn-result","cat":"connector","grp":"result","topic":"Cause and effect","level":"B2","note":"'Therefore', 'consequently' and 'as a result' usually start a new sentence (after a full stop or semicolon) and are followed by a comma. 'Thus' is more formal and can also join two verbs: '...reduced its waste and thus saved money'.","items":[{"t":"therefore","pos":"linker","ex":"The roads were icy; therefore, many schools closed."},{"t":"consequently","pos":"linker","ex":"Prices rose sharply. Consequently, fewer people could afford to travel."},{"t":"as a result","pos":"linker","ex":"He trained hard every day. As a result, his fitness improved."},{"t":"thus","pos":"linker","ex":"The company reduced its waste and thus saved money."}]},{"id":"cn-contrast-clause","cat":"connector","grp":"contrast","topic":"Contrast","level":"B2","note":"All three introduce an unexpected contrast and are followed by a full clause. 'Even though' is stronger than 'although'; 'though' is more informal and can also come at the end of a sentence.","items":[{"t":"although","pos":"conj","ex":"Although the course was expensive, it was worth the money."},{"t":"though","pos":"conj","ex":"Though he was tired, he finished the report."},{"t":"even though","pos":"conj","ex":"Even though it rained all day, the festival went ahead."}]},{"id":"cn-contrast-compare","cat":"connector","grp":"contrast","topic":"Contrast","level":"B2","note":"These compare two different facts inside ONE sentence (A is X, whereas B is Y). 'Whilst' is the formal, mainly British form.","items":[{"t":"whereas","pos":"conj","ex":"Urban areas are crowded, whereas rural areas are quiet."},{"t":"while","pos":"conj","ex":"Some people prefer cities, while others love the countryside."},{"t":"whilst","pos":"conj","ex":"Salaries have risen, whilst living costs have risen faster."}]},{"id":"cn-contrast-noun","cat":"connector","grp":"contrast","topic":"Contrast","level":"B2","note":"Followed by a noun, a pronoun or an -ing form (never by a clause), and never 'despite of'. 'Notwithstanding' is very formal and can also follow its noun.","items":[{"t":"despite","pos":"prep","ex":"Despite the high cost, the project went ahead."},{"t":"in spite of","pos":"prep","ex":"In spite of the warnings, many people ignored the flood risk."},{"t":"notwithstanding","pos":"prep","ex":"Notwithstanding their objections, the council approved the plan."}]},{"id":"cn-contrast-linker","cat":"connector","grp":"contrast","topic":"Contrast","level":"C1","note":"These start a new sentence (or follow a semicolon) and are followed by a comma. 'Nonetheless' and 'nevertheless' are the most formal; 'even so' is the most natural in speech.","items":[{"t":"however","pos":"linker","ex":"The plan is cheap. However, it will take years to complete."},{"t":"nevertheless","pos":"linker","ex":"The results were disappointing; nevertheless, the team kept going."},{"t":"nonetheless","pos":"linker","ex":"The task was difficult. Nonetheless, she finished on time."},{"t":"even so","pos":"linker","ex":"Prices have fallen. Even so, many families cannot afford a home."}]},{"id":"cn-addition","cat":"connector","grp":"addition","topic":"Adding ideas","level":"B2","note":"All add a further point. 'Moreover' and 'furthermore' are formal; 'besides' and 'what is more' sound less formal and often add a stronger or final argument.","items":[{"t":"moreover","pos":"linker","ex":"The scheme is cheap. Moreover, it is easy to use."},{"t":"furthermore","pos":"linker","ex":"Exercise improves health. Furthermore, it boosts mood."},{"t":"in addition","pos":"linker","ex":"In addition, students receive free books."},{"t":"what is more","pos":"linker","ex":"He is talented and, what is more, he works extremely hard."},{"t":"besides","pos":"linker","ex":"I don't want to go; besides, it is too late."}]},{"id":"cn-purpose","cat":"connector","grp":"purpose","topic":"Purpose","level":"B2","note":"All express purpose. 'In order to' and 'so as to' are followed by the base verb; 'so that' is followed by a clause (often with can/could/will/would); 'with a view to' is followed by an -ing form.","items":[{"t":"in order to","pos":"phrase","ex":"Governments tax sugar in order to reduce obesity."},{"t":"so as to","pos":"phrase","ex":"Cities limit cars so as to cut pollution."},{"t":"so that","pos":"conj","ex":"Schools should start later so that teenagers can sleep longer."},{"t":"with a view to","pos":"phrase","ex":"The firm is training staff with a view to expanding abroad."}]},{"id":"cn-condition","cat":"connector","grp":"condition","topic":"Condition","level":"B2","note":"All four mean 'only if'. 'On condition that' is formal; 'as long as' is the most common in speech. They are followed by a present tense to talk about the future.","items":[{"t":"provided that","pos":"conj","ex":"Tuition fees are acceptable provided that grants are available."},{"t":"providing","pos":"conj","ex":"You can borrow it, providing you return it on Friday."},{"t":"as long as","pos":"conj","ex":"Remote work is fine as long as deadlines are met."},{"t":"on condition that","pos":"conj","ex":"The loan was approved on condition that the money was repaid in a year."}]},{"id":"cn-time-after","cat":"connector","grp":"time-after","topic":"Time and sequence","level":"B2","note":"All describe what happens next. 'Subsequently' and 'thereafter' are formal; 'later on' and 'afterwards' are neutral and common in speech.","items":[{"t":"afterwards","pos":"adv","ex":"We had dinner and went for a walk afterwards."},{"t":"subsequently","pos":"adv","ex":"The law was subsequently changed."},{"t":"later on","pos":"adv","ex":"Later on, she moved to London."},{"t":"thereafter","pos":"adv","ex":"He left school at sixteen and worked thereafter as a mechanic."}]},{"id":"cn-exemplify","cat":"connector","grp":"exemplify","topic":"Giving examples","level":"B2","note":"'Such as' is followed by a noun or a list, never by a full sentence. 'To illustrate' introduces a longer example. 'For example' and 'for instance' are interchangeable.","items":[{"t":"for example","pos":"linker","ex":"Many cities have congestion. For example, London introduced a charge."},{"t":"for instance","pos":"linker","ex":"Some jobs are disappearing. For instance, bank tellers."},{"t":"such as","pos":"phrase","ex":"Fruits such as apples and pears are rich in fibre."},{"t":"to illustrate","pos":"phrase","ex":"To illustrate, a worker earning the average salary can no longer afford a flat."}]},{"id":"cn-emphasis","cat":"connector","grp":"emphasis","topic":"Emphasis","level":"B2","note":"These introduce a fact that is true or more accurate than what was just said. 'In reality' contrasts a belief with the truth.","items":[{"t":"in fact","pos":"linker","ex":"Many people think cycling is slow. In fact, it is often faster in cities."},{"t":"as a matter of fact","pos":"linker","ex":"I enjoy maths; as a matter of fact, I teach it."},{"t":"in reality","pos":"linker","ex":"It looks simple, but in reality it takes years of practice."},{"t":"indeed","pos":"linker","ex":"The project was a success; indeed, it exceeded every target."}]},{"id":"cn-conclude","cat":"connector","grp":"conclude","topic":"Concluding","level":"B2","note":"Use only to start the final paragraph or the last sentence. Avoid 'at last', which means 'after a long wait'.","items":[{"t":"in conclusion","pos":"linker","ex":"In conclusion, the benefits of remote work outweigh the drawbacks."},{"t":"to sum up","pos":"linker","ex":"To sum up, both views have merit."},{"t":"in summary","pos":"linker","ex":"In summary, governments should invest in public transport."},{"t":"all in all","pos":"linker","ex":"All in all, I believe the advantages are greater."}]},{"id":"cn-opinion","cat":"connector","grp":"opinion","topic":"Giving your opinion","level":"B2","note":"Safe ways to state a position in the introduction or conclusion of a Task 2 essay. 'As far as I am concerned' is a little less formal.","items":[{"t":"in my opinion","pos":"phrase","ex":"In my opinion, school uniforms should be compulsory."},{"t":"in my view","pos":"phrase","ex":"In my view, the government should act now."},{"t":"from my perspective","pos":"phrase","ex":"From my perspective, the main cause is poverty."},{"t":"as far as I am concerned","pos":"phrase","ex":"As far as I am concerned, online learning is here to stay."}]},{"id":"cn-generally","cat":"connector","grp":"generally","topic":"Generalising","level":"B2","note":"All introduce a general statement that has exceptions. 'By and large' is slightly informal.","items":[{"t":"generally","pos":"adv","ex":"Generally, young people adapt quickly to new technology."},{"t":"on the whole","pos":"phrase","ex":"On the whole, the scheme has been successful."},{"t":"by and large","pos":"phrase","ex":"By and large, people support the new law."},{"t":"in general","pos":"phrase","ex":"In general, rents are higher in the capital."}]},{"id":"cn-similar","cat":"connector","grp":"similar","topic":"Similarity","level":"B2","note":"All show that a second point is like the first. 'Likewise' and 'similarly' are the most formal.","items":[{"t":"similarly","pos":"linker","ex":"Cars pollute the air. Similarly, aeroplanes damage the atmosphere."},{"t":"likewise","pos":"linker","ex":"Governments must act; businesses must likewise take responsibility."},{"t":"in the same way","pos":"phrase","ex":"In the same way, small shops struggle to compete with online stores."},{"t":"equally","pos":"linker","ex":"Equally, parents have a role in children's education."}]},{"id":"cn-restate","cat":"connector","grp":"restate","topic":"Rephrasing","level":"B2","note":"Use when you explain an idea more simply or more precisely.","items":[{"t":"in other words","pos":"phrase","ex":"The population is ageing; in other words, there are more elderly people."},{"t":"that is to say","pos":"phrase","ex":"The scheme is voluntary, that is to say nobody is forced to join."},{"t":"to put it another way","pos":"phrase","ex":"To put it another way, cheap food is rarely healthy."}]},{"id":"cn-regarding","cat":"connector","grp":"regarding","topic":"Introducing a topic","level":"B2","note":"All mean 'about' and introduce a topic. 'With regard to' and 'in relation to' sound the most formal. Never write 'with regards to'.","items":[{"t":"regarding","pos":"prep","ex":"Regarding public transport, opinions are divided."},{"t":"with regard to","pos":"phrase","ex":"With regard to cost, online courses are far cheaper."},{"t":"concerning","pos":"prep","ex":"Questions concerning safety should be sent to the manager."},{"t":"in relation to","pos":"phrase","ex":"Salaries in relation to living costs have fallen."}]},{"id":"cn-now","cat":"connector","grp":"now","topic":"Time","level":"B2","note":"All refer to the present period. 'At present' and 'currently' are slightly more formal than 'nowadays' and 'these days'.","items":[{"t":"nowadays","pos":"adv","ex":"Nowadays, most people shop online."},{"t":"these days","pos":"adv","ex":"These days, children spend hours on screens."},{"t":"at present","pos":"phrase","ex":"At present, the city has no underground railway."},{"t":"currently","pos":"adv","ex":"The company is currently recruiting new staff."}]},{"id":"cn-gradual","cat":"connector","grp":"gradual","topic":"Time","level":"B2","note":"All describe slow change over time. 'Progressively' is more formal and implies steady improvement or worsening.","items":[{"t":"gradually","pos":"adv","ex":"The climate is gradually getting warmer."},{"t":"step by step","pos":"phrase","ex":"Step by step, she built her own business."},{"t":"little by little","pos":"phrase","ex":"Little by little, the town recovered after the flood."},{"t":"progressively","pos":"adv","ex":"Exam results have progressively improved."}]},{"id":"cn-priority","cat":"connector","grp":"priority","topic":"Emphasis","level":"B2","note":"Use to put one point above the others. 'First and foremost' often opens an argument.","items":[{"t":"above all","pos":"phrase","ex":"Above all, children need a safe environment."},{"t":"most importantly","pos":"adv","ex":"Most importantly, the plan must be affordable."},{"t":"first and foremost","pos":"phrase","ex":"First and foremost, schools should teach critical thinking."},{"t":"more than anything","pos":"phrase","ex":"More than anything, patients want to be listened to."}]},{"id":"cn-partly","cat":"connector","grp":"partly","topic":"Partly agreeing","level":"C1","note":"Useful in Task 2 when you partly agree with a statement. All mean 'not completely'.","items":[{"t":"to some extent","pos":"phrase","ex":"I agree with this view to some extent."},{"t":"to a certain degree","pos":"phrase","ex":"To a certain degree, technology has made us lonelier."},{"t":"up to a point","pos":"phrase","ex":"Up to a point, competition motivates students."},{"t":"in part","pos":"phrase","ex":"The crisis was caused in part by poor planning."}]},{"id":"cn-obvious","cat":"connector","grp":"obvious","topic":"Certainty","level":"B2","note":"All show strong certainty. 'Evidently' and 'undoubtedly' are the most formal; 'clearly' is the safest in writing.","items":[{"t":"obviously","pos":"adv","ex":"Obviously, nobody wants to pay higher taxes."},{"t":"clearly","pos":"adv","ex":"Clearly, the current system is not working."},{"t":"evidently","pos":"adv","ex":"Evidently, the policy has failed."},{"t":"undoubtedly","pos":"adv","ex":"Exercise is undoubtedly good for mental health."}]},{"id":"t1-rise","cat":"task1","grp":"increase","topic":"Describing trends","level":"B2","note":"Rise, climb and go up have no object ('Sales rose'); 'increase' and 'grow' can be used the same way. Use the past tense for past years: rose, climbed, went up, increased, grew.","items":[{"t":"rise","pos":"verb","ex":"The figure rose from 12% to 28% between 2000 and 2005.","k":"rose"},{"t":"climb","pos":"verb","ex":"Internet use climbed steadily after 2010.","k":"climbed"},{"t":"go up","pos":"verb","ex":"The cost of housing went up in every year shown.","k":"went up"},{"t":"increase","pos":"verb","ex":"The number of visitors increased by 20%.","k":"increased"}]},{"id":"t1-fall","cat":"task1","grp":"decrease","topic":"Describing trends","level":"B2","note":"Fall, decline, drop and go down have no object. 'Decrease' is the most formal. Past forms: fell, declined, dropped, went down, decreased.","items":[{"t":"fall","pos":"verb","ex":"The percentage of smokers fell from 30% to 18%.","k":"fell"},{"t":"decline","pos":"verb","ex":"Newspaper sales declined throughout the decade.","k":"declined"},{"t":"drop","pos":"verb","ex":"Unemployment dropped to 5% in 2015.","k":"dropped"},{"t":"go down","pos":"verb","ex":"The price of mobile phones went down sharply.","k":"went down"}]},{"id":"t1-rise-sharp","cat":"task1","grp":"increase","topic":"Describing trends","level":"C1","note":"These describe a sudden, large rise. 'Soar' and 'surge' are the most common; 'rocket' and 'shoot up' are slightly more dramatic.","items":[{"t":"soar","pos":"verb","ex":"Electric car sales soared after 2018.","k":"soared"},{"t":"surge","pos":"verb","ex":"Demand surged in the final year.","k":"surged"},{"t":"rocket","pos":"verb","ex":"Online shopping rocketed during the pandemic.","k":"rocketed"},{"t":"shoot up","pos":"verb","ex":"Prices shot up in the following month.","k":"shot up"}]},{"id":"t1-fall-sharp","cat":"task1","grp":"decrease","topic":"Describing trends","level":"C1","note":"These describe a sudden, large fall. 'Plunge' and 'plummet' are the strongest; 'slump' and 'tumble' suggest a drop in value or performance.","items":[{"t":"plunge","pos":"verb","ex":"Profits plunged from $9 million to $2 million.","k":"plunged"},{"t":"plummet","pos":"verb","ex":"Oil prices plummeted in 2015.","k":"plummeted"},{"t":"slump","pos":"verb","ex":"Sales slumped in the winter months.","k":"slumped"},{"t":"tumble","pos":"verb","ex":"Share prices tumbled after the announcement.","k":"tumbled"}]},{"id":"t1-stable","cat":"task1","grp":"stable","topic":"Describing trends","level":"B2","note":"All describe a figure that stays almost the same. 'Level off' and 'plateau' follow a period of change; 'remain stable' can be used for any period.","items":[{"t":"remain stable","pos":"verb","ex":"The figure remained stable at around 40% for ten years.","k":"remained stable"},{"t":"level off","pos":"verb","ex":"The numbers levelled off after 2010.","k":"levelled off"},{"t":"plateau","pos":"verb","ex":"Sales plateaued in the final three years.","k":"plateaued"},{"t":"stay constant","pos":"verb","ex":"The rate stayed constant throughout the period.","k":"stayed constant"}]},{"id":"t1-fluctuate","cat":"task1","grp":"fluctuate","topic":"Describing trends","level":"B2","note":"All describe a figure that keeps changing in both directions. 'See-saw' is informal but vivid; 'fluctuate' is the standard word.","items":[{"t":"fluctuate","pos":"verb","ex":"Prices fluctuated between $40 and $60 a barrel.","k":"fluctuated"},{"t":"vary","pos":"verb","ex":"Temperatures varied widely from month to month.","k":"varied"},{"t":"go up and down","pos":"phrase","ex":"The figure went up and down over the decade.","k":"went up and down"},{"t":"see-saw","pos":"verb","ex":"Support for the policy see-sawed throughout the year.","k":"see-sawed"}]},{"id":"t1-peak","cat":"task1","grp":"peak","topic":"Describing trends","level":"C1","note":"All describe the highest point. Use 'peak at' and 'top out at' with a figure.","items":[{"t":"peak at","pos":"phrase","ex":"Sales peaked at 5 million units in 2012.","k":"peaked at"},{"t":"hit a high of","pos":"phrase","ex":"The rate hit a high of 12% in 2008.","k":"hit a high of"},{"t":"reach its highest point","pos":"phrase","ex":"The figure reached its highest point in July.","k":"reached its highest point"},{"t":"top out at","pos":"phrase","ex":"Growth topped out at 4% before falling.","k":"topped out at"}]},{"id":"t1-trough","cat":"task1","grp":"trough","topic":"Describing trends","level":"C1","note":"All describe the lowest point. 'Bottom out' suggests the fall then stops and starts to recover.","items":[{"t":"bottom out","pos":"phrase","ex":"Prices bottomed out in 2009 and then recovered.","k":"bottomed out"},{"t":"hit a low of","pos":"phrase","ex":"The figure hit a low of 3% in 1995.","k":"hit a low of"},{"t":"reach its lowest point","pos":"phrase","ex":"Attendance reached its lowest point in January.","k":"reached its lowest point"},{"t":"reach a trough","pos":"phrase","ex":"The market reached a trough in March.","k":"reached a trough"}]},{"id":"t1-most","cat":"task1","grp":"amount-large","topic":"Quantities","level":"B2","note":"All describe a large part of a whole. 'The bulk of' and 'the majority of' are used with a plural or uncountable noun.","items":[{"t":"the majority of","pos":"phrase","ex":"The majority of respondents preferred online shopping."},{"t":"the bulk of","pos":"phrase","ex":"The bulk of the budget went on salaries."},{"t":"a large proportion of","pos":"phrase","ex":"A large proportion of students live at home."},{"t":"most","pos":"det","ex":"Most households owned a car by 1990."}]},{"id":"t1-few","cat":"task1","grp":"amount-small","topic":"Quantities","level":"B2","note":"All describe a small part. 'A handful of' is informal and only for a small countable number; 'a minority of' is used when you compare with a majority.","items":[{"t":"a minority of","pos":"phrase","ex":"Only a minority of employees worked from home."},{"t":"a small proportion of","pos":"phrase","ex":"A small proportion of income was spent on books."},{"t":"a handful of","pos":"phrase","ex":"A handful of countries produce most of the world's coffee."},{"t":"only a few","pos":"phrase","ex":"Only a few families had a computer in 1995."}]},{"id":"t1-approx","cat":"task1","grp":"approx","topic":"Quantities","level":"B2","note":"All mean 'not exact'. Put them before the number. 'In the region of' is the most formal.","items":[{"t":"approximately","pos":"adv","ex":"Approximately 60% of the budget was spent on staff."},{"t":"roughly","pos":"adv","ex":"Roughly a third of students failed."},{"t":"around","pos":"adv","ex":"Around 2,000 people attended."},{"t":"in the region of","pos":"phrase","ex":"The population was in the region of 5 million."}]},{"id":"t1-quarter","cat":"task1","grp":"fractions","topic":"Quantities","level":"B2","note":"Different ways to say 25%. 'One in four' is common for people; use 'a quarter of' with a noun.","items":[{"t":"a quarter of","pos":"phrase","ex":"A quarter of the workforce was over 50."},{"t":"one in four","pos":"phrase","ex":"One in four adults had a degree."},{"t":"25 per cent of","pos":"phrase","ex":"25 per cent of the land was farmland."},{"t":"one fourth of","pos":"phrase","ex":"One fourth of the income came from tourism."}]},{"id":"t1-exceed","cat":"task1","grp":"exceed","topic":"Comparing","level":"C1","note":"All mean 'be more than'. 'Outstrip' suggests growing faster than something else; 'surpass' suggests overtaking.","items":[{"t":"exceed","pos":"verb","ex":"Imports exceeded exports by $2 billion.","k":"exceeded"},{"t":"surpass","pos":"verb","ex":"Solar power surpassed coal in 2020.","k":"surpassed"},{"t":"outstrip","pos":"verb","ex":"Demand outstripped supply for most of the decade.","k":"outstripped"},{"t":"be higher than","pos":"phrase","ex":"Salaries in finance were higher than those in education.","k":"were higher than"}]},{"id":"t1-similar","cat":"task1","grp":"similar","topic":"Comparing","level":"B2","note":"All say two things are almost the same. 'On a par with' means at the same level.","items":[{"t":"similar to","pos":"phrase","ex":"The figure for Japan was similar to that of Korea."},{"t":"comparable to","pos":"phrase","ex":"Prices in the north are comparable to those in the south."},{"t":"on a par with","pos":"phrase","ex":"Women's pay is now on a par with men's in this sector."},{"t":"much the same as","pos":"phrase","ex":"The rate in 2020 was much the same as in 2010."}]},{"id":"t1-period","cat":"task1","grp":"period","topic":"Time","level":"B2","note":"All refer to the whole time span shown. 'Throughout' and 'over the period' are the most common in Task 1.","items":[{"t":"over the period","pos":"phrase","ex":"The figure rose steadily over the period."},{"t":"throughout the period","pos":"phrase","ex":"Rent stayed high throughout the period."},{"t":"during the whole period","pos":"phrase","ex":"Rainfall was low during the whole period."},{"t":"across the timeframe","pos":"phrase","ex":"There was little change across the timeframe."}]},{"id":"t1-notable","cat":"task1","grp":"notable","topic":"Highlighting","level":"C1","note":"Use to introduce the key feature of a chart. 'Striking' and 'remarkable' are stronger than 'notable'.","items":[{"t":"striking","pos":"adj","ex":"The most striking feature is the rise in solar power."},{"t":"notable","pos":"adj","ex":"A notable difference is the gap between men and women."},{"t":"noteworthy","pos":"adj","ex":"It is noteworthy that exports fell in every year."},{"t":"remarkable","pos":"adj","ex":"There was a remarkable increase in online sales."}]},{"id":"pt-lack","cat":"pattern","grp":"lack","topic":"Lack and shortage","level":"B2","note":"All say there is not enough of something. 'Lack of', 'shortage of' and 'scarcity of' are nouns (followed by a noun); 'insufficient' and 'inadequate' are adjectives that go BEFORE a noun. 'Shortage' is used for things that are needed; 'scarcity' for things that are rare.","items":[{"t":"lack of","pos":"noun phrase","ex":"A lack of affordable housing is forcing young people to leave the city."},{"t":"shortage of","pos":"noun phrase","ex":"The shortage of nurses is putting pressure on hospitals."},{"t":"scarcity of","pos":"noun phrase","ex":"The scarcity of clean water affects millions of people."},{"t":"insufficient","pos":"adj","ex":"Insufficient funding has delayed the project."},{"t":"inadequate","pos":"adj","ex":"Inadequate sleep reduces concentration."}]},{"id":"pt-without","cat":"pattern","grp":"lack","topic":"Lack and shortage","level":"C1","note":"All express 'not having something'. 'Without' is followed by a noun or -ing form; 'in the absence of' and 'devoid of' are formal; 'lacking in' is followed by a quality.","items":[{"t":"without","pos":"prep","ex":"Many people cannot live without a mobile phone."},{"t":"in the absence of","pos":"phrase","ex":"In the absence of clear evidence, the court released him."},{"t":"devoid of","pos":"phrase","ex":"The speech was devoid of any real meaning."},{"t":"lacking in","pos":"phrase","ex":"The report is lacking in detail."}]},{"id":"pt-jobless","cat":"pattern","grp":"unemployed","topic":"Word-building: -less = without","level":"B2","note":"The suffix -less means 'without' (jobless = without a job). It makes useful, compact adjectives: homeless, hopeless, pointless, careless. All four of these describe someone with no work.","items":[{"t":"jobless","pos":"adj","ex":"Jobless young people often struggle to find housing."},{"t":"unemployed","pos":"adj","ex":"The number of unemployed graduates has risen."},{"t":"out of work","pos":"phrase","ex":"Thousands of factory workers are out of work."},{"t":"without a job","pos":"phrase","ex":"He has been without a job for six months."}]},{"id":"pt-able","cat":"pattern","grp":"able","topic":"Ability","level":"B2","note":"All express ability. 'Manage to' suggests succeeding with effort; 'be capable of' suggests having the potential; 'be able to' and 'have the ability to' are neutral.","items":[{"t":"be able to","pos":"phrase","ex":"Students should be able to choose their own subjects.","k":"be able to"},{"t":"be capable of","pos":"phrase","ex":"Children are capable of learning two languages at once.","k":"are capable of"},{"t":"have the ability to","pos":"phrase","ex":"Leaders must have the ability to listen.","k":"have the ability to"},{"t":"manage to","pos":"phrase","ex":"Despite the delay, we managed to finish on time.","k":"managed to"}]},{"id":"pt-tend","cat":"pattern","grp":"tend","topic":"Tendency","level":"B2","note":"All express a general tendency rather than a rule. 'Be likely to' is about probability; the others describe habit.","items":[{"t":"tend to","pos":"phrase","ex":"Young people tend to adapt quickly to new technology.","k":"tend to"},{"t":"be inclined to","pos":"phrase","ex":"Many people are inclined to trust information they see online.","k":"are inclined to"},{"t":"have a tendency to","pos":"phrase","ex":"Teenagers have a tendency to stay up late.","k":"have a tendency to"},{"t":"be prone to","pos":"phrase","ex":"Cities near rivers are prone to flooding.","k":"are prone to"}]},{"id":"pt-prefer","cat":"pattern","grp":"prefer","topic":"Preference","level":"B2","note":"All show a choice. 'Opt for' and 'choose' are followed by a noun; 'favour' is formal.","items":[{"t":"prefer","pos":"verb","ex":"Many commuters prefer the train to the bus.","k":"prefer"},{"t":"opt for","pos":"phrase","ex":"More families are opting for smaller homes.","k":"opting for"},{"t":"choose","pos":"verb","ex":"Some students choose to study abroad.","k":"choose"},{"t":"favour","pos":"verb","ex":"Most voters favour lower taxes.","k":"favour"}]},{"id":"pt-allow","cat":"pattern","grp":"allow","topic":"Permission","level":"B2","note":"'Allow', 'enable' and 'permit' are followed by an object + to-infinitive (allow people TO vote). 'Let' is followed by an object + base verb WITHOUT 'to' (let people vote). 'Enable' means 'make possible'.","items":[{"t":"allow","pos":"verb","ex":"Smartphones allow us to work from anywhere.","k":"allow"},{"t":"enable","pos":"verb","ex":"Online banking enables customers to pay bills instantly.","k":"enables"},{"t":"permit","pos":"verb","ex":"The law does not permit children to work at night.","k":"permit"},{"t":"let","pos":"verb","ex":"Some schools let students use phones at lunchtime.","k":"let"}]},{"id":"pt-force","cat":"pattern","grp":"force","topic":"Obligation","level":"C1","note":"All mean 'make someone do something'. 'Oblige' and 'compel' are formal; 'force' is the strongest and suggests no choice.","items":[{"t":"force","pos":"verb","ex":"High rents force many families to leave the city.","k":"force"},{"t":"oblige","pos":"verb","ex":"The law obliges employers to provide safe conditions.","k":"obliges"},{"t":"compel","pos":"verb","ex":"Poverty compels some children to leave school.","k":"compels"},{"t":"make","pos":"verb","ex":"Heavy traffic makes people leave home earlier.","k":"makes"}]},{"id":"pt-argued","cat":"pattern","grp":"say","topic":"Reporting views","level":"B2","note":"These passive 'it' structures report what people think or say without naming them, and are followed by 'that' + clause. They suit the introduction of a Task 2 essay.","items":[{"t":"it is argued that","pos":"phrase","ex":"It is argued that cities should ban cars from their centres."},{"t":"it is claimed that","pos":"phrase","ex":"It is claimed that video games improve concentration."},{"t":"it is widely believed that","pos":"phrase","ex":"It is widely believed that exercise improves mental health."},{"t":"there is a widespread view that","pos":"phrase","ex":"There is a widespread view that university is essential for success."}]},{"id":"pt-many","cat":"pattern","grp":"many","topic":"Quantity words","level":"B2","note":"All mean 'a large number'. 'Countless' and 'a multitude of' are stronger and slightly literary; 'a wide range of' stresses variety.","items":[{"t":"numerous","pos":"adj","ex":"Numerous studies have linked sugar to heart disease."},{"t":"a great many","pos":"phrase","ex":"A great many people have no access to clean water."},{"t":"countless","pos":"adj","ex":"Countless families depend on tourism."},{"t":"a wide range of","pos":"phrase","ex":"The course offers a wide range of subjects."}]},{"id":"tp-green","cat":"topic","grp":"green","topic":"Environment","level":"B2","note":"All describe something that does not harm nature. 'Eco-friendly' is common for products; 'ecologically sound' is formal and describes policies or methods.","items":[{"t":"environmentally friendly","pos":"adj","ex":"Electric buses are an environmentally friendly alternative to diesel."},{"t":"eco-friendly","pos":"adj","ex":"Eco-friendly packaging is becoming more popular."},{"t":"green","pos":"adj","ex":"Many firms now advertise green products."},{"t":"ecologically sound","pos":"adj","ex":"The government promotes ecologically sound farming methods."}]},{"id":"tp-protect","cat":"topic","grp":"protect","topic":"Environment","level":"B2","note":"'Protect' and 'safeguard' mean keep from harm; 'preserve' means keep exactly as it is (heritage, forests); 'conserve' means use carefully so it lasts (water, energy).","items":[{"t":"protect","pos":"verb","ex":"National parks protect wildlife.","k":"protect"},{"t":"safeguard","pos":"verb","ex":"Strict laws safeguard rare species.","k":"safeguard"},{"t":"preserve","pos":"verb","ex":"We must preserve ancient forests for future generations.","k":"preserve"},{"t":"conserve","pos":"verb","ex":"Households can conserve water by fixing leaks.","k":"conserve"}]},{"id":"tp-reduce","cat":"topic","grp":"reduce","topic":"Environment","level":"B2","note":"All mean 'make smaller'. 'Curb' means control something harmful; 'minimise' means reduce to the smallest possible amount.","items":[{"t":"reduce","pos":"verb","ex":"Cities must reduce traffic emissions.","k":"reduce"},{"t":"cut","pos":"verb","ex":"The firm plans to cut its energy use by 30%.","k":"cut"},{"t":"curb","pos":"verb","ex":"Higher taxes could curb the use of plastic bags.","k":"curb"},{"t":"minimise","pos":"verb","ex":"Good design minimises waste.","k":"minimises"}]},{"id":"tp-eradicate","cat":"topic","grp":"eradicate","topic":"Environment","level":"C1","note":"All mean 'get rid of completely'. 'Eradicate' and 'stamp out' are used for diseases, crime and poverty; 'wipe out' can also describe destruction.","items":[{"t":"eradicate","pos":"verb","ex":"Vaccination helped eradicate smallpox.","k":"eradicate"},{"t":"eliminate","pos":"verb","ex":"The aim is to eliminate plastic waste by 2030.","k":"eliminate"},{"t":"wipe out","pos":"phrase","ex":"Overfishing has wiped out some species.","k":"wiped out"},{"t":"stamp out","pos":"phrase","ex":"Governments are trying to stamp out corruption.","k":"stamp out"}]},{"id":"tp-warming","cat":"topic","grp":"warming","topic":"Environment","level":"B2","note":"'Climate change' is the broad term (changing weather patterns); 'global warming' and 'rising global temperatures' refer specifically to the increase in average temperature.","items":[{"t":"global warming","pos":"noun","ex":"Global warming is melting the polar ice."},{"t":"climate change","pos":"noun","ex":"Climate change threatens coastal cities."},{"t":"rising global temperatures","pos":"noun phrase","ex":"Rising global temperatures are causing more heatwaves."},{"t":"the climate crisis","pos":"noun phrase","ex":"The climate crisis requires urgent international action."}]},{"id":"tp-rubbish","cat":"topic","grp":"rubbish","topic":"Environment","level":"B2","note":"All refer to things thrown away. 'Rubbish' is British, 'garbage' and 'trash' American; 'waste' is more formal and also covers industrial waste; 'refuse' is official language.","items":[{"t":"rubbish","pos":"noun","ex":"The streets were covered in rubbish."},{"t":"waste","pos":"noun","ex":"Food waste is a growing problem."},{"t":"garbage","pos":"noun","ex":"Garbage is collected twice a week."},{"t":"refuse","pos":"noun","ex":"Refuse collection is the council's responsibility."}]},{"id":"tp-renewable","cat":"topic","grp":"renewable","topic":"Environment","level":"B2","note":"All describe energy that does not run out or pollute. 'Renewable' stresses that it is replaced naturally; 'clean' stresses no pollution; 'sustainable' stresses it can continue long term.","items":[{"t":"renewable energy","pos":"noun phrase","ex":"Many countries are investing in renewable energy."},{"t":"clean energy","pos":"noun phrase","ex":"Clean energy creates new jobs."},{"t":"sustainable energy","pos":"noun phrase","ex":"Sustainable energy is essential for the future."},{"t":"green energy","pos":"noun phrase","ex":"Green energy now powers over half of the city."}]},{"id":"tp-endangered","cat":"topic","grp":"endangered","topic":"Environment","level":"B2","note":"All describe species that may disappear. 'On the verge of extinction' is the most severe.","items":[{"t":"endangered","pos":"adj","ex":"The tiger is an endangered species."},{"t":"threatened","pos":"adj","ex":"Several threatened birds nest on the island."},{"t":"at risk of extinction","pos":"phrase","ex":"Hundreds of plants are at risk of extinction."},{"t":"on the verge of extinction","pos":"phrase","ex":"The rhino is on the verge of extinction."}]},{"id":"tp-compulsory","cat":"topic","grp":"compulsory","topic":"Education","level":"B2","note":"All mean 'must be done'. 'Compulsory' and 'mandatory' are the most common; 'obligatory' is more formal.","items":[{"t":"compulsory","pos":"adj","ex":"Education is compulsory until the age of sixteen."},{"t":"mandatory","pos":"adj","ex":"Safety training is mandatory for all staff."},{"t":"obligatory","pos":"adj","ex":"Attendance at the lecture is obligatory."},{"t":"required","pos":"adj","ex":"A second language is required for graduation."}]},{"id":"tp-curriculum","cat":"topic","grp":"curriculum","topic":"Education","level":"B2","note":"'Curriculum' is everything a school teaches; 'syllabus' is the list of topics in one course.","items":[{"t":"curriculum","pos":"noun","ex":"The national curriculum should include financial literacy."},{"t":"syllabus","pos":"noun","ex":"The syllabus for this course is available online."},{"t":"programme of study","pos":"noun phrase","ex":"Students follow a programme of study chosen with their tutor."},{"t":"course content","pos":"noun phrase","ex":"The course content is updated every year."}]},{"id":"tp-gifted","cat":"topic","grp":"talented","topic":"Education","level":"B2","note":"All describe people with high ability. 'Gifted' suggests natural ability; 'bright' is informal; 'academically able' is neutral and formal.","items":[{"t":"gifted","pos":"adj","ex":"Gifted children often need extra challenges."},{"t":"talented","pos":"adj","ex":"She is a talented young musician."},{"t":"bright","pos":"adj","ex":"He was a bright student who always asked questions."},{"t":"academically able","pos":"adj","ex":"Academically able pupils may be taught in a separate class."}]},{"id":"tp-dropout","cat":"topic","grp":"dropout","topic":"Education","level":"B2","note":"All describe leaving education before finishing. 'Drop out' is the most common; the others sound slightly more formal.","items":[{"t":"drop out of school","pos":"phrase","ex":"Many teenagers drop out of school to earn money.","k":"drop out of school"},{"t":"quit school","pos":"phrase","ex":"He quit school at fifteen.","k":"quit school"},{"t":"leave school early","pos":"phrase","ex":"Boys are more likely to leave school early.","k":"leave school early"},{"t":"give up their studies","pos":"phrase","ex":"Some students give up their studies because of the cost.","k":"give up their studies"}]},{"id":"tp-acquire","cat":"topic","grp":"acquire","topic":"Education","level":"B2","note":"All describe getting new knowledge or skills. 'Pick up' is informal and suggests learning without formal study; 'acquire' is formal; 'develop' means improve what you already have.","items":[{"t":"pick up","pos":"phrase","ex":"You can pick up a language quickly by living abroad.","k":"pick up"},{"t":"acquire","pos":"verb","ex":"Graduates acquire skills that employers value.","k":"acquire"},{"t":"gain","pos":"verb","ex":"Interns gain valuable experience.","k":"gain"},{"t":"develop","pos":"verb","ex":"Team sports help children develop confidence.","k":"develop"}]},{"id":"tp-mistake","cat":"topic","grp":"mistake","topic":"Education","level":"B2","note":"All mean something done wrongly. 'Slip' is a small careless mistake; 'blunder' is a serious one; 'error' is the neutral formal word; 'oversight' is something you forgot to notice.","items":[{"t":"mistake","pos":"noun","ex":"Everyone makes mistakes when learning a language."},{"t":"error","pos":"noun","ex":"The test contained several spelling errors."},{"t":"slip","pos":"noun","ex":"It was only a slip of the pen."},{"t":"blunder","pos":"noun","ex":"Hiring him was a costly blunder."}]},{"id":"tp-cutting","cat":"topic","grp":"advanced","topic":"Technology","level":"C1","note":"All describe the newest, most advanced ideas. 'Groundbreaking' and 'pioneering' stress being the first; 'cutting-edge' and 'state-of-the-art' stress being the most modern.","items":[{"t":"cutting-edge","pos":"adj","ex":"The hospital uses cutting-edge surgical technology."},{"t":"state-of-the-art","pos":"adj","ex":"The school has a state-of-the-art science laboratory."},{"t":"groundbreaking","pos":"adj","ex":"The study produced groundbreaking results."},{"t":"pioneering","pos":"adj","ex":"She led pioneering research into artificial intelligence."}]},{"id":"tp-outdated","cat":"topic","grp":"outdated","topic":"Technology","level":"B2","note":"All describe something no longer modern or useful. 'Obsolete' means no longer used at all; 'old-fashioned' is neutral to negative; 'antiquated' is stronger.","items":[{"t":"outdated","pos":"adj","ex":"Many schools still use outdated textbooks."},{"t":"obsolete","pos":"adj","ex":"Typewriters have become obsolete."},{"t":"out of date","pos":"adj","ex":"The software is out of date and needs updating."},{"t":"antiquated","pos":"adj","ex":"The city's antiquated transport system causes delays."}]},{"id":"tp-addicted","cat":"topic","grp":"addicted","topic":"Technology","level":"B2","note":"All describe being unable to stop using something. 'Hooked on' is informal; 'dependent on' is more neutral and suggests need.","items":[{"t":"addicted to","pos":"phrase","ex":"Many teenagers are addicted to their phones."},{"t":"hooked on","pos":"phrase","ex":"I got hooked on a TV series last month."},{"t":"dependent on","pos":"phrase","ex":"Modern society is heavily dependent on electricity."},{"t":"obsessed with","pos":"phrase","ex":"Some people are obsessed with checking social media."}]},{"id":"tp-spread","cat":"topic","grp":"spread","topic":"Technology","level":"C1","note":"All describe information, news or disease moving to more people. 'Disseminate' is formal and used for information; 'transmit' is also used for signals and diseases.","items":[{"t":"spread","pos":"verb","ex":"Rumours spread quickly on social media.","k":"spread"},{"t":"circulate","pos":"verb","ex":"False stories circulate widely online.","k":"circulate"},{"t":"disseminate","pos":"verb","ex":"Universities disseminate research through journals.","k":"disseminate"},{"t":"transmit","pos":"verb","ex":"Mosquitoes can transmit serious diseases.","k":"transmit"}]},{"id":"tp-userfriendly","cat":"topic","grp":"userfriendly","topic":"Technology","level":"B2","note":"All describe something simple to use. 'Intuitive' means you can use it without instructions.","items":[{"t":"user-friendly","pos":"adj","ex":"The new app is very user-friendly."},{"t":"easy to use","pos":"phrase","ex":"The website is easy to use."},{"t":"intuitive","pos":"adj","ex":"The software has an intuitive design."},{"t":"accessible","pos":"adj","ex":"Online banking is accessible to people of all ages."}]},{"id":"tp-harmful","cat":"topic","grp":"harmful","topic":"Health","level":"B2","note":"All describe something that causes damage. 'Detrimental' and 'adverse' are formal; 'detrimental to' and 'harmful to' are followed by the thing that suffers.","items":[{"t":"detrimental","pos":"adj","ex":"Lack of sleep is detrimental to health."},{"t":"harmful","pos":"adj","ex":"Smoking is harmful to almost every organ."},{"t":"damaging","pos":"adj","ex":"Junk food is damaging to children's teeth."},{"t":"adverse","pos":"adj","ex":"The drug had adverse effects on some patients."}]},{"id":"tp-sedentary","cat":"topic","grp":"inactive","topic":"Health","level":"B2","note":"All describe not moving much. 'Sedentary' is the most formal and is used with 'lifestyle'.","items":[{"t":"a sedentary lifestyle","pos":"noun phrase","ex":"A sedentary lifestyle increases the risk of heart disease."},{"t":"an inactive lifestyle","pos":"noun phrase","ex":"An inactive lifestyle is common among office workers."},{"t":"a lack of exercise","pos":"noun phrase","ex":"A lack of exercise affects mental health too."},{"t":"a couch-potato lifestyle","pos":"noun phrase","ex":"A couch-potato lifestyle is bad for your health."}]},{"id":"tp-stress","cat":"topic","grp":"stress","topic":"Health","level":"B2","note":"All describe mental or physical pressure. 'Strain' often suggests long-term effort; 'tension' can also mean bad feeling between people.","items":[{"t":"stress","pos":"noun","ex":"Work-related stress is a major cause of illness."},{"t":"pressure","pos":"noun","ex":"Students are under great pressure to succeed."},{"t":"strain","pos":"noun","ex":"Long hours put a strain on family life."},{"t":"tension","pos":"noun","ex":"There was a lot of tension in the office."}]},{"id":"tp-recover","cat":"topic","grp":"recover","topic":"Health","level":"B2","note":"All describe becoming healthy again. 'Get better' and 'get over' are informal and common in speech; 'recuperate' means rest and regain strength.","items":[{"t":"recover","pos":"verb","ex":"Most patients recover within two weeks.","k":"recover"},{"t":"get better","pos":"phrase","ex":"I hope you get better soon.","k":"get better"},{"t":"recuperate","pos":"verb","ex":"He is recuperating at home after the operation.","k":"recuperating"},{"t":"get over","pos":"phrase","ex":"It took her a month to get over the flu.","k":"get over"}]},{"id":"tp-nutritious","cat":"topic","grp":"nutritious","topic":"Health","level":"B2","note":"All describe food that is good for you.","items":[{"t":"nutritious","pos":"adj","ex":"Schools should serve nutritious meals."},{"t":"wholesome","pos":"adj","ex":"She cooks simple, wholesome food."},{"t":"healthy","pos":"adj","ex":"A healthy diet includes plenty of vegetables."},{"t":"nourishing","pos":"adj","ex":"A nourishing breakfast helps children concentrate."}]},{"id":"tp-pay","cat":"topic","grp":"pay","topic":"Work","level":"B2","note":"'Salary' is fixed pay, usually monthly; 'wage' is usually paid by the hour or week; 'earnings' is everything a person earns from work; 'income' includes money from any source.","items":[{"t":"salary","pos":"noun","ex":"The average salary for teachers has risen."},{"t":"wage","pos":"noun","ex":"The minimum wage will increase next year."},{"t":"earnings","pos":"noun","ex":"Average earnings in the region are low."},{"t":"income","pos":"noun","ex":"Household income has fallen in real terms."}]},{"id":"tp-hire","cat":"topic","grp":"hire","topic":"Work","level":"B2","note":"All mean 'give someone a job'. 'Recruit' suggests searching for and selecting people; 'take on' is informal.","items":[{"t":"hire","pos":"verb","ex":"The company plans to hire 200 new staff.","k":"hire"},{"t":"recruit","pos":"verb","ex":"Hospitals struggle to recruit enough nurses.","k":"recruit"},{"t":"employ","pos":"verb","ex":"The factory employs over a thousand people.","k":"employs"},{"t":"take on","pos":"phrase","ex":"The shop took on two extra workers for the holiday season.","k":"took on"}]},{"id":"tp-dismiss","cat":"topic","grp":"dismiss","topic":"Work","level":"B2","note":"All mean 'make someone leave their job'. 'Sack' and 'fire' are informal; 'dismiss' is formal and official; 'let go' is polite and often used when a company reduces staff.","items":[{"t":"dismiss","pos":"verb","ex":"He was dismissed for being late too often.","k":"dismissed"},{"t":"sack","pos":"verb","ex":"The club sacked its manager after six defeats.","k":"sacked"},{"t":"fire","pos":"verb","ex":"She was fired for breaking company rules.","k":"fired"},{"t":"let go","pos":"phrase","ex":"The firm let go of fifty employees last year.","k":"let go"}]},{"id":"tp-colleague","cat":"topic","grp":"colleague","topic":"Work","level":"B2","note":"All mean a person you work with. 'Colleague' is the standard word in formal English.","items":[{"t":"colleague","pos":"noun","ex":"I get on well with my colleagues."},{"t":"co-worker","pos":"noun","ex":"My co-workers organised a surprise party."},{"t":"workmate","pos":"noun","ex":"A workmate recommended the restaurant."},{"t":"fellow employee","pos":"noun","ex":"He asked a fellow employee for advice."}]},{"id":"tp-retire","cat":"topic","grp":"retire","topic":"Work","level":"B2","note":"All describe stopping working, usually because of age.","items":[{"t":"retire","pos":"verb","ex":"Many people retire at sixty-five.","k":"retire"},{"t":"give up work","pos":"phrase","ex":"She gave up work to look after her mother.","k":"gave up work"},{"t":"stop working","pos":"phrase","ex":"He stopped working at sixty.","k":"stopped working"},{"t":"leave the workforce","pos":"phrase","ex":"Many women leave the workforce after having children.","k":"leave the workforce"}]},{"id":"tp-prospects","cat":"topic","grp":"prospects","topic":"Work","level":"C1","note":"All describe chances to move up in a career.","items":[{"t":"career prospects","pos":"noun phrase","ex":"A degree improves your career prospects."},{"t":"promotion opportunities","pos":"noun phrase","ex":"There are few promotion opportunities in small firms."},{"t":"chances of promotion","pos":"noun phrase","ex":"Speaking English increases your chances of promotion."},{"t":"opportunities for advancement","pos":"noun phrase","ex":"The company offers excellent opportunities for advancement."}]},{"id":"tp-criminal","cat":"topic","grp":"criminal","topic":"Crime","level":"B2","note":"All name someone who breaks the law. 'Offender' is the official word; 'perpetrator' is the person who carried out a particular crime.","items":[{"t":"criminal","pos":"noun","ex":"Many criminals reoffend after leaving prison."},{"t":"offender","pos":"noun","ex":"Young offenders should receive education, not just punishment."},{"t":"lawbreaker","pos":"noun","ex":"Lawbreakers should face fair trials."},{"t":"perpetrator","pos":"noun","ex":"The perpetrator of the fraud has been arrested."}]},{"id":"tp-punishment","cat":"topic","grp":"punishment","topic":"Crime","level":"B2","note":"'Punishment' is the general word; 'penalty' is the set consequence for breaking a rule; 'sanction' is an official penalty, often against a country or company; 'sentence' is the punishment given by a court.","items":[{"t":"punishment","pos":"noun","ex":"Is prison the best punishment for minor crimes?"},{"t":"penalty","pos":"noun","ex":"The penalty for speeding is a heavy fine."},{"t":"sanction","pos":"noun","ex":"The country faces economic sanctions."},{"t":"sentence","pos":"noun","ex":"The judge gave him a two-year sentence."}]},{"id":"tp-deter","cat":"topic","grp":"deter","topic":"Crime","level":"C1","note":"All mean 'make someone less likely to do something'. 'Deter' and 'dissuade' are followed by 'from + -ing'; 'put off' is informal.","items":[{"t":"deter","pos":"verb","ex":"Harsh fines deter drivers from speeding.","k":"deter"},{"t":"discourage","pos":"verb","ex":"High prices discourage people from using public transport.","k":"discourage"},{"t":"dissuade","pos":"verb","ex":"Parents tried to dissuade him from leaving school.","k":"dissuade"},{"t":"put off","pos":"phrase","ex":"The cost put many students off studying abroad.","k":"put many students off"}]},{"id":"tp-harsh","cat":"topic","grp":"harsh","topic":"Crime","level":"B2","note":"All describe a strong, unpleasant response. 'Stringent' describes rules that are very strict; 'tough' is informal.","items":[{"t":"harsh","pos":"adj","ex":"Harsh penalties may not reduce crime."},{"t":"severe","pos":"adj","ex":"The court imposed a severe punishment."},{"t":"stringent","pos":"adj","ex":"The country has stringent gun laws."},{"t":"tough","pos":"adj","ex":"The government promised tough measures against fraud."}]},{"id":"tp-fake","cat":"topic","grp":"fake","topic":"Media","level":"B2","note":"All describe false information. 'Disinformation' is spread on purpose; 'misinformation' may be spread by mistake.","items":[{"t":"fake news","pos":"noun phrase","ex":"Fake news spreads faster than the truth."},{"t":"misinformation","pos":"noun","ex":"Misinformation about health can be dangerous."},{"t":"disinformation","pos":"noun","ex":"The campaign was based on deliberate disinformation."},{"t":"false information","pos":"noun phrase","ex":"Social media platforms must remove false information."}]},{"id":"tp-celebrity","cat":"topic","grp":"celebrity","topic":"Media","level":"B2","note":"All describe famous people. 'A household name' is someone known by almost everybody.","items":[{"t":"celebrity","pos":"noun","ex":"Young people often copy the habits of celebrities.","k":"celebrities"},{"t":"public figure","pos":"noun phrase","ex":"Public figures should set a good example."},{"t":"star","pos":"noun","ex":"Film stars earn huge salaries."},{"t":"household name","pos":"noun phrase","ex":"The singer became a household name overnight."}]},{"id":"tp-congestion","cat":"topic","grp":"congestion","topic":"Cities and transport","level":"B2","note":"All describe too many vehicles on the road. 'Gridlock' means traffic that cannot move at all.","items":[{"t":"congestion","pos":"noun","ex":"Traffic congestion costs the economy billions."},{"t":"traffic jams","pos":"noun phrase","ex":"Traffic jams are common during rush hour."},{"t":"gridlock","pos":"noun","ex":"Gridlock paralysed the city centre."},{"t":"heavy traffic","pos":"noun phrase","ex":"Heavy traffic makes the journey take twice as long."}]},{"id":"tp-crowded","cat":"topic","grp":"crowded","topic":"Cities and transport","level":"B2","note":"All mean 'too full of people'. 'Jam-packed' is informal and very strong.","items":[{"t":"crowded","pos":"adj","ex":"The underground is very crowded in the morning."},{"t":"overcrowded","pos":"adj","ex":"Overcrowded classrooms make it hard to learn."},{"t":"packed","pos":"adj","ex":"The stadium was packed with fans."},{"t":"jam-packed","pos":"adj","ex":"The market was jam-packed at the weekend."}]},{"id":"tp-affordable","cat":"topic","grp":"cheap","topic":"Cities and transport","level":"B2","note":"All describe something that costs little. 'Affordable' means ordinary people can pay for it; 'inexpensive' is neutral; 'economical' means it saves money.","items":[{"t":"affordable","pos":"adj","ex":"Affordable housing is scarce in big cities."},{"t":"reasonably priced","pos":"adj","ex":"The hotel is clean and reasonably priced."},{"t":"inexpensive","pos":"adj","ex":"Bicycles are an inexpensive way to travel."},{"t":"economical","pos":"adj","ex":"Small cars are more economical to run."}]},{"id":"tp-expensive","cat":"topic","grp":"expensive","topic":"Cities and transport","level":"B2","note":"All describe something that costs a lot. 'Pricey' is informal; 'exorbitant' means unreasonably high.","items":[{"t":"expensive","pos":"adj","ex":"Housing in the capital is extremely expensive."},{"t":"costly","pos":"adj","ex":"Mistakes can be costly."},{"t":"pricey","pos":"adj","ex":"The restaurant is lovely but a bit pricey."},{"t":"exorbitant","pos":"adj","ex":"Landlords charge exorbitant rents."}]},{"id":"tp-centre","cat":"topic","grp":"centre","topic":"Cities and transport","level":"B2","note":"All mean the main area of a town. 'Downtown' is American English.","items":[{"t":"city centre","pos":"noun phrase","ex":"Parking in the city centre is expensive."},{"t":"town centre","pos":"noun phrase","ex":"The town centre is closed to cars on Sundays."},{"t":"downtown","pos":"noun","ex":"She works downtown."},{"t":"the heart of the city","pos":"noun phrase","ex":"The museum is in the heart of the city."}]},{"id":"tp-rural","cat":"topic","grp":"rural","topic":"Cities and transport","level":"B2","note":"All describe places outside big cities.","items":[{"t":"rural areas","pos":"noun phrase","ex":"Broadband is slow in rural areas."},{"t":"the countryside","pos":"noun phrase","ex":"Many retired people move to the countryside."},{"t":"country areas","pos":"noun phrase","ex":"Doctors are scarce in country areas."},{"t":"the provinces","pos":"noun phrase","ex":"Salaries in the provinces are lower than in the capital."}]},{"id":"tp-bringup","cat":"topic","grp":"raise","topic":"Family and society","level":"B2","note":"All describe looking after children until they are adults. 'Bring up' is the most common; 'rear' is formal and also used for animals; 'nurture' stresses care and encouragement.","items":[{"t":"bring up","pos":"phrase","ex":"Grandparents often help bring up the children.","k":"bring up"},{"t":"raise","pos":"verb","ex":"She raised three children on her own.","k":"raised"},{"t":"rear","pos":"verb","ex":"They reared their family in a small village.","k":"reared"},{"t":"nurture","pos":"verb","ex":"Good teachers nurture talent.","k":"nurture"}]},{"id":"tp-elderly","cat":"topic","grp":"elderly","topic":"Family and society","level":"B2","note":"All refer to older people. In formal writing avoid 'old people', which can sound rude; 'senior citizens' is polite.","items":[{"t":"elderly people","pos":"noun phrase","ex":"Elderly people need good healthcare."},{"t":"senior citizens","pos":"noun phrase","ex":"Senior citizens travel free on buses."},{"t":"older adults","pos":"noun phrase","ex":"Older adults can learn new skills."},{"t":"pensioners","pos":"noun","ex":"Many pensioners live on a low income."}]},{"id":"tp-poverty","cat":"topic","grp":"poverty","topic":"Family and society","level":"C1","note":"All describe lack of money. 'Hardship' is difficult conditions; 'deprivation' is lacking basic needs; 'destitution' is extreme poverty.","items":[{"t":"poverty","pos":"noun","ex":"Poverty affects children's education."},{"t":"hardship","pos":"noun","ex":"Many families faced hardship during the recession."},{"t":"deprivation","pos":"noun","ex":"Some areas suffer from serious deprivation."},{"t":"destitution","pos":"noun","ex":"Thousands lived in destitution after the floods."}]},{"id":"tp-wealthy","cat":"topic","grp":"wealthy","topic":"Family and society","level":"B2","note":"All describe people with plenty of money. 'Affluent' and 'prosperous' are formal; 'well-off' is neutral and common.","items":[{"t":"wealthy","pos":"adj","ex":"Wealthy families can afford private schools."},{"t":"affluent","pos":"adj","ex":"The city has many affluent neighbourhoods."},{"t":"well-off","pos":"adj","ex":"They are not rich, but they are quite well-off."},{"t":"prosperous","pos":"adj","ex":"The region became prosperous through trade."}]},{"id":"tp-attraction","cat":"topic","grp":"attraction","topic":"Travel and culture","level":"B2","note":"All refer to places visitors like to see. 'Landmark' is a famous building or feature.","items":[{"t":"tourist attraction","pos":"noun phrase","ex":"The castle is the city's main tourist attraction."},{"t":"place of interest","pos":"noun phrase","ex":"The guide lists the best places of interest.","k":"places of interest"},{"t":"landmark","pos":"noun","ex":"The tower is a famous landmark."},{"t":"popular destination","pos":"noun phrase","ex":"Bali is a popular destination for honeymoons."}]},{"id":"tp-holiday","cat":"topic","grp":"holiday","topic":"Travel and culture","level":"B2","note":"All describe time away from work. 'Vacation' is American English; 'getaway' is a short escape.","items":[{"t":"holiday","pos":"noun","ex":"We are going on holiday in August."},{"t":"vacation","pos":"noun","ex":"They spent their vacation in Canada."},{"t":"break","pos":"noun","ex":"I need a break from the city."},{"t":"getaway","pos":"noun","ex":"A weekend getaway can be very relaxing."}]},{"id":"tp-tradition","cat":"topic","grp":"custom","topic":"Travel and culture","level":"B2","note":"All describe habits or beliefs passed down in a society. 'Convention' is an accepted way of behaving.","items":[{"t":"tradition","pos":"noun","ex":"The festival is an old tradition in the region."},{"t":"custom","pos":"noun","ex":"It is the custom to remove shoes before entering."},{"t":"convention","pos":"noun","ex":"Formal dress is still the convention at weddings."},{"t":"practice","pos":"noun","ex":"The practice of arranged marriage is declining."}]},{"id":"tp-fund","cat":"topic","grp":"fund","topic":"Economy","level":"B2","note":"'Fund' and 'finance' mean provide money; 'sponsor' usually means a company supporting an event; 'subsidise' means help pay so the price is lower.","items":[{"t":"fund","pos":"verb","ex":"The government funds university research.","k":"funds"},{"t":"finance","pos":"verb","ex":"The new road will be financed by taxes.","k":"financed"},{"t":"sponsor","pos":"verb","ex":"A bank sponsors the national football team.","k":"sponsors"},{"t":"subsidise","pos":"verb","ex":"The state subsidises public transport.","k":"subsidises"}]},{"id":"tp-economy","cat":"topic","grp":"economy","topic":"Economy","level":"C1","note":"All mean 'make the economy stronger'.","items":[{"t":"stimulate","pos":"verb","ex":"Lower interest rates can stimulate the economy.","k":"stimulate"},{"t":"revitalise","pos":"verb","ex":"The festival helped revitalise the old town.","k":"revitalise"},{"t":"strengthen","pos":"verb","ex":"Trade agreements strengthen the economy.","k":"strengthen"},{"t":"invigorate","pos":"verb","ex":"New industries have invigorated the region.","k":"invigorated"}]},{"id":"gn-show","cat":"general","grp":"show","topic":"Reporting verbs","level":"B2","note":"All mean 'make something clear'. 'Reveal' suggests uncovering something hidden; 'indicate' suggests a sign.","items":[{"t":"show","pos":"verb","ex":"The chart shows a steady rise in sales.","k":"shows"},{"t":"demonstrate","pos":"verb","ex":"The study demonstrates the benefits of exercise.","k":"demonstrates"},{"t":"illustrate","pos":"verb","ex":"This example illustrates the problem.","k":"illustrates"},{"t":"reveal","pos":"verb","ex":"The survey reveals a lack of awareness.","k":"reveals"}]},{"id":"gn-claim","cat":"general","grp":"claim","topic":"Reporting verbs","level":"C1","note":"All mean 'say that something is true'. 'Maintain' and 'assert' show strong belief; 'contend' is formal and used in arguments.","items":[{"t":"claim","pos":"verb","ex":"Critics claim that the plan is too expensive.","k":"claim"},{"t":"maintain","pos":"verb","ex":"He maintains that he is innocent.","k":"maintains"},{"t":"contend","pos":"verb","ex":"Some economists contend that taxes should be lower.","k":"contend"},{"t":"assert","pos":"verb","ex":"The minister asserted that the policy was working.","k":"asserted"}]},{"id":"gn-need","cat":"general","grp":"need","topic":"Verbs","level":"B2","note":"All express need. 'Call for' and 'demand' are stronger and often used for actions or changes.","items":[{"t":"need","pos":"verb","ex":"Developing countries need more investment.","k":"need"},{"t":"require","pos":"verb","ex":"The course requires daily practice.","k":"requires"},{"t":"call for","pos":"phrase","ex":"Experts call for stricter regulation.","k":"call for"},{"t":"demand","pos":"verb","ex":"The situation demands immediate action.","k":"demands"}]},{"id":"gn-help","cat":"general","grp":"help","topic":"Verbs","level":"B2","note":"All mean 'make something easier or better'. 'Aid' is formal; 'assist' is more formal than 'help'.","items":[{"t":"help","pos":"verb","ex":"Volunteers help elderly neighbours.","k":"help"},{"t":"assist","pos":"verb","ex":"Teaching assistants assist the class teacher.","k":"assist"},{"t":"aid","pos":"verb","ex":"New drugs aid recovery.","k":"aid"},{"t":"support","pos":"verb","ex":"Parents support their children's education.","k":"support"}]},{"id":"gn-start","cat":"general","grp":"start","topic":"Verbs","level":"B2","note":"All mean 'begin'. 'Commence' is formal; 'embark on' suggests starting a big journey or project.","items":[{"t":"start","pos":"verb","ex":"Classes start at nine.","k":"start"},{"t":"begin","pos":"verb","ex":"The ceremony will begin shortly.","k":"begin"},{"t":"commence","pos":"verb","ex":"Construction will commence in March.","k":"commence"},{"t":"embark on","pos":"phrase","ex":"She embarked on a career in medicine.","k":"embarked on"}]},{"id":"gn-use","cat":"general","grp":"use","topic":"Verbs","level":"B2","note":"All mean 'use'. 'Utilise' is formal; 'make use of' stresses getting benefit from something; 'draw on' means use a source such as experience, knowledge or savings.","items":[{"t":"use","pos":"verb","ex":"Most people use smartphones daily.","k":"use"},{"t":"utilise","pos":"verb","ex":"Schools should utilise digital tools.","k":"utilise"},{"t":"draw on","pos":"phrase","ex":"Writers often draw on their own experience.","k":"draw on"},{"t":"make use of","pos":"phrase","ex":"Students should make use of the library.","k":"make use of"}]},{"id":"gn-try","cat":"general","grp":"try","topic":"Verbs","level":"B2","note":"All mean 'try'. 'Endeavour' and 'strive' are formal and suggest serious effort.","items":[{"t":"try","pos":"verb","ex":"Governments try to reduce unemployment.","k":"try"},{"t":"attempt","pos":"verb","ex":"She attempted to learn three languages at once.","k":"attempted"},{"t":"endeavour","pos":"verb","ex":"We endeavour to answer all questions within a day.","k":"endeavour"},{"t":"strive","pos":"verb","ex":"Athletes strive to improve every day.","k":"strive"}]},{"id":"gn-enough","cat":"general","grp":"enough","topic":"Adjectives","level":"B2","note":"All mean 'as much as is needed'. 'Ample' means more than enough.","items":[{"t":"enough","pos":"adj","ex":"Do you have enough time?"},{"t":"sufficient","pos":"adj","ex":"Sufficient evidence is needed to convict a suspect."},{"t":"adequate","pos":"adj","ex":"Adequate sleep is vital for teenagers."},{"t":"ample","pos":"adj","ex":"There is ample parking at the station."}]},{"id":"gn-important","cat":"general","grp":"important","topic":"Adjectives","level":"B2","note":"All mean 'very important'. 'Pivotal' means the key point on which something turns; 'of paramount importance' is the strongest.","items":[{"t":"crucial","pos":"adj","ex":"Teachers play a crucial role in a child's development."},{"t":"vital","pos":"adj","ex":"Clean water is vital for health."},{"t":"essential","pos":"adj","ex":"Exercise is essential for a healthy life."},{"t":"pivotal","pos":"adj","ex":"The decision was pivotal to the company's success."}]},{"id":"gn-serious","cat":"general","grp":"serious","topic":"Adjectives","level":"B2","note":"All describe a very bad problem. 'Acute' is used for shortages and pain; 'grave' is formal; 'pressing' means needing action now.","items":[{"t":"serious","pos":"adj","ex":"Obesity is a serious problem."},{"t":"grave","pos":"adj","ex":"Experts have grave concerns about the plan."},{"t":"acute","pos":"adj","ex":"There is an acute shortage of teachers."},{"t":"pressing","pos":"adj","ex":"Housing is the most pressing issue for young people."}]},{"id":"gn-cause","cat":"general","grp":"cause","topic":"Cause and effect","level":"B2","note":"All mean 'make something happen'. 'Give rise to' and 'bring about' are formal; 'trigger' suggests a sudden start.","items":[{"t":"cause","pos":"verb","ex":"Pollution can cause serious illness.","k":"cause"},{"t":"lead to","pos":"phrase","ex":"Poverty often leads to crime.","k":"leads to"},{"t":"result in","pos":"phrase","ex":"Poor planning resulted in long delays.","k":"resulted in"},{"t":"give rise to","pos":"phrase","ex":"Rapid growth gave rise to new problems.","k":"gave rise to"},{"t":"bring about","pos":"phrase","ex":"The internet has brought about huge social changes.","k":"brought about"}]},{"id":"gn-encourage","cat":"general","grp":"encourage","topic":"Verbs","level":"B2","note":"All mean 'make something more likely to happen'. 'Foster' is formal and used for ideas and relationships.","items":[{"t":"encourage","pos":"verb","ex":"Schools should encourage creativity.","k":"encourage"},{"t":"promote","pos":"verb","ex":"Campaigns promote healthy eating.","k":"promote"},{"t":"foster","pos":"verb","ex":"Sport fosters teamwork.","k":"fosters"},{"t":"spur","pos":"verb","ex":"Competition spurs innovation.","k":"spurs"}]},{"id":"gn-improve","cat":"general","grp":"improve","topic":"Verbs","level":"B2","note":"All mean 'make better'. 'Enhance' is formal; 'upgrade' often means replacing with a better version.","items":[{"t":"improve","pos":"verb","ex":"Exercise improves memory.","k":"improves"},{"t":"enhance","pos":"verb","ex":"Technology can enhance learning.","k":"enhance"},{"t":"upgrade","pos":"verb","ex":"The city plans to upgrade its railways.","k":"upgrade"},{"t":"boost","pos":"verb","ex":"Tourism boosts local businesses.","k":"boosts"}]},{"id":"gn-solution","cat":"general","grp":"solution","topic":"Problems and solutions","level":"B2","note":"All mean a way to deal with a problem. 'Remedy' is formal and suggests curing something.","items":[{"t":"solution","pos":"noun","ex":"Education is the best solution to poverty."},{"t":"remedy","pos":"noun","ex":"There is no simple remedy for unemployment."},{"t":"answer","pos":"noun","ex":"Banning cars is not the answer."},{"t":"resolution","pos":"noun","ex":"Both sides hope for a peaceful resolution."}]},{"id":"gn-problem","cat":"general","grp":"problem","topic":"Problems and solutions","level":"B2","note":"All mean something difficult. 'Obstacle' is something in the way of progress; 'challenge' is a positive word for a difficulty.","items":[{"t":"problem","pos":"noun","ex":"Pollution is a major problem."},{"t":"difficulty","pos":"noun","ex":"Many learners have difficulty with pronunciation."},{"t":"challenge","pos":"noun","ex":"Climate change is the biggest challenge of our time."},{"t":"obstacle","pos":"noun","ex":"Cost is the main obstacle to studying abroad."}]},{"id":"gn-disadvantage","cat":"general","grp":"disadvantage","topic":"Advantages and disadvantages","level":"B2","note":"All mean a negative point. 'Pitfall' is a hidden danger; 'downside' is informal.","items":[{"t":"drawback","pos":"noun","ex":"The main drawback of the plan is the cost."},{"t":"downside","pos":"noun","ex":"The downside of fame is the lack of privacy."},{"t":"shortcoming","pos":"noun","ex":"The report highlights several shortcomings."},{"t":"pitfall","pos":"noun","ex":"Beware of the pitfalls of buying online."}]},{"id":"gn-advantage","cat":"general","grp":"advantage","topic":"Advantages and disadvantages","level":"B2","note":"All mean a positive point. 'Merit' is formal; 'upside' is informal.","items":[{"t":"advantage","pos":"noun","ex":"The main advantage of remote work is flexibility."},{"t":"benefit","pos":"noun","ex":"Regular exercise has many benefits."},{"t":"merit","pos":"noun","ex":"Both proposals have their merits."},{"t":"upside","pos":"noun","ex":"The upside is lower costs."}]},{"id":"sp-sad","cat":"speaking","grp":"sad","topic":"Feelings","level":"B2","note":"All mean 'feel unhappy'. 'Feel down', 'feel low' and 'feel blue' are natural and informal; 'be in low spirits' is more formal. Use them after 'feel' or 'be'.","items":[{"t":"feel down","pos":"phrase","ex":"I've been feeling down since I failed the exam.","k":"feeling down"},{"t":"feel low","pos":"phrase","ex":"Everyone feels low in winter when the days are short.","k":"feels low"},{"t":"feel blue","pos":"phrase","ex":"I felt blue after my best friend moved away.","k":"felt blue"},{"t":"feel miserable","pos":"phrase","ex":"He felt miserable about leaving his hometown.","k":"felt miserable"},{"t":"be in low spirits","pos":"phrase","ex":"She has been in low spirits all week.","k":"in low spirits"}]},{"id":"sp-happy","cat":"speaking","grp":"happy","topic":"Feelings","level":"B2","note":"All mean 'very happy'. 'Over the moon' and 'on cloud nine' are idioms; 'thrilled' and 'delighted' are neutral and safe in the exam.","items":[{"t":"over the moon","pos":"idiom","ex":"I was over the moon when I got my results."},{"t":"on cloud nine","pos":"idiom","ex":"She was on cloud nine after the wedding."},{"t":"thrilled","pos":"adj","ex":"We were thrilled to hear the good news."},{"t":"delighted","pos":"adj","ex":"I'm delighted with my new flat."}]},{"id":"sp-angry","cat":"speaking","grp":"angry","topic":"Feelings","level":"B2","note":"All mean 'very angry'. 'Fuming' and 'livid' show strong anger; 'irritated' is milder.","items":[{"t":"furious","pos":"adj","ex":"I was furious when the train was cancelled again."},{"t":"livid","pos":"adj","ex":"My boss was livid about the mistake."},{"t":"fuming","pos":"adj","ex":"He was fuming after waiting for two hours."},{"t":"irritated","pos":"adj","ex":"I get irritated when people talk loudly in cafés."}]},{"id":"sp-tired","cat":"speaking","grp":"tired","topic":"Feelings","level":"B2","note":"All mean 'very tired'. 'Shattered' and 'knackered' are informal and British; 'exhausted' is neutral.","items":[{"t":"exhausted","pos":"adj","ex":"I was exhausted after the long flight."},{"t":"worn out","pos":"adj","ex":"The kids were worn out after the trip."},{"t":"drained","pos":"adj","ex":"Meetings all day leave me completely drained."},{"t":"shattered","pos":"adj","ex":"I'm absolutely shattered after work."}]},{"id":"sp-stressed","cat":"speaking","grp":"stressed","topic":"Feelings","level":"B2","note":"All mean 'feeling too much pressure'. 'Overwhelmed' means there is too much to deal with.","items":[{"t":"stressed out","pos":"adj","ex":"I'm stressed out about the deadline."},{"t":"under pressure","pos":"phrase","ex":"Students feel under pressure before exams."},{"t":"overwhelmed","pos":"adj","ex":"I felt overwhelmed by all the homework."},{"t":"on edge","pos":"phrase","ex":"She has been on edge all day."}]},{"id":"sp-worried","cat":"speaking","grp":"worried","topic":"Feelings","level":"B2","note":"All mean 'a little afraid that something bad may happen'. 'Apprehensive' is more formal.","items":[{"t":"anxious","pos":"adj","ex":"I felt anxious before the interview."},{"t":"concerned","pos":"adj","ex":"Parents are concerned about screen time."},{"t":"uneasy","pos":"adj","ex":"He felt uneasy walking home alone."},{"t":"apprehensive","pos":"adj","ex":"I was apprehensive about moving abroad."}]},{"id":"sp-surprised","cat":"speaking","grp":"surprised","topic":"Feelings","level":"B2","note":"All mean 'very surprised'. 'Gobsmacked' is informal and British; 'taken aback' means shocked in a mild way.","items":[{"t":"astonished","pos":"adj","ex":"I was astonished by how cheap the tickets were."},{"t":"taken aback","pos":"phrase","ex":"I was taken aback by his honesty."},{"t":"amazed","pos":"adj","ex":"We were amazed at the size of the city."},{"t":"stunned","pos":"adj","ex":"The audience was stunned by the news."},{"t":"gobsmacked","pos":"adj","ex":"I was gobsmacked when I saw the bill."}]},{"id":"sp-great","cat":"speaking","grp":"great","topic":"Describing things","level":"B2","note":"All mean 'very good'. Choose one that matches the thing: 'superb' and 'outstanding' for quality, 'fantastic' and 'brilliant' for enthusiasm.","items":[{"t":"excellent","pos":"adj","ex":"The food was excellent."},{"t":"outstanding","pos":"adj","ex":"She gave an outstanding presentation."},{"t":"superb","pos":"adj","ex":"The view from the hotel was superb."},{"t":"brilliant","pos":"adj","ex":"We had a brilliant time at the festival."}]},{"id":"sp-awful","cat":"speaking","grp":"awful","topic":"Describing things","level":"B2","note":"All mean 'very bad'. 'Appalling' and 'atrocious' are the strongest; 'dreadful' is common in British English.","items":[{"t":"awful","pos":"adj","ex":"The weather was awful all week."},{"t":"terrible","pos":"adj","ex":"I had a terrible journey home."},{"t":"dreadful","pos":"adj","ex":"The service was dreadful."},{"t":"appalling","pos":"adj","ex":"The state of the roads is appalling."}]},{"id":"sp-interesting","cat":"speaking","grp":"interesting","topic":"Describing things","level":"B2","note":"All mean 'very interesting'. 'Gripping' is used for stories and films; 'captivating' for performances and people.","items":[{"t":"fascinating","pos":"adj","ex":"I find ancient history fascinating."},{"t":"intriguing","pos":"adj","ex":"It's an intriguing idea."},{"t":"captivating","pos":"adj","ex":"The singer gave a captivating performance."},{"t":"gripping","pos":"adj","ex":"The novel was so gripping that I read it in a night."}]},{"id":"sp-boring","cat":"speaking","grp":"boring","topic":"Describing things","level":"B2","note":"All mean 'not interesting'. 'Tedious' and 'monotonous' describe tasks that are long and repetitive.","items":[{"t":"dull","pos":"adj","ex":"The lecture was rather dull."},{"t":"tedious","pos":"adj","ex":"Filling in forms is a tedious job."},{"t":"monotonous","pos":"adj","ex":"Factory work can be monotonous."},{"t":"mind-numbing","pos":"adj","ex":"The meeting was mind-numbing."}]},{"id":"sp-agree","cat":"speaking","grp":"agree","topic":"Agreeing and disagreeing","level":"B2","note":"All show agreement. 'I couldn't agree more' is strong; 'you're right' is friendly and common in Part 3 discussions.","items":[{"t":"I couldn't agree more","pos":"phrase","ex":"I couldn't agree more; cities need more green spaces."},{"t":"absolutely","pos":"adv","ex":"Absolutely, education should be free."},{"t":"you're right","pos":"phrase","ex":"You're right, social media can be harmful."},{"t":"I totally agree","pos":"phrase","ex":"I totally agree that exercise is important."}]},{"id":"sp-disagree","cat":"speaking","grp":"disagree","topic":"Agreeing and disagreeing","level":"B2","note":"Polite ways to disagree. 'I'm not so sure' is the softest; 'that's debatable' invites discussion.","items":[{"t":"I'm not so sure","pos":"phrase","ex":"I'm not so sure that working from home is better."},{"t":"I see it differently","pos":"phrase","ex":"I see it differently, actually."},{"t":"I don't really agree","pos":"phrase","ex":"I don't really agree with that view."},{"t":"that's debatable","pos":"phrase","ex":"That's debatable; some studies say the opposite."}]},{"id":"sp-opinion","cat":"speaking","grp":"opinion","topic":"Giving your opinion","level":"B2","note":"Natural ways to give an opinion in Speaking. 'I reckon' and 'if you ask me' are informal; 'I'd say' is neutral.","items":[{"t":"I reckon","pos":"phrase","ex":"I reckon most people prefer shopping online."},{"t":"I'd say","pos":"phrase","ex":"I'd say the biggest problem is traffic."},{"t":"it seems to me","pos":"phrase","ex":"It seems to me that people read less these days."},{"t":"if you ask me","pos":"phrase","ex":"If you ask me, school starts too early."}]},{"id":"sp-usually","cat":"speaking","grp":"usually","topic":"Frequency","level":"B2","note":"All mean 'most of the time'. 'As a rule' and 'more often than not' are natural in Part 1.","items":[{"t":"normally","pos":"adv","ex":"I normally get up at seven."},{"t":"as a rule","pos":"phrase","ex":"As a rule, I don't eat out on weekdays."},{"t":"more often than not","pos":"phrase","ex":"More often than not, I walk to work."},{"t":"typically","pos":"adv","ex":"Typically, my weekends are quiet."}]},{"id":"sp-often","cat":"speaking","grp":"often","topic":"Frequency","level":"B2","note":"All mean 'many times'.","items":[{"t":"frequently","pos":"adv","ex":"I frequently travel for work."},{"t":"regularly","pos":"adv","ex":"I regularly meet my friends on Sundays."},{"t":"time and again","pos":"phrase","ex":"Time and again, he forgets his keys."},{"t":"on a regular basis","pos":"phrase","ex":"I exercise on a regular basis."}]},{"id":"sp-rarely","cat":"speaking","grp":"rarely","topic":"Frequency","level":"B2","note":"All mean 'not often'. 'Once in a blue moon' is an idiom meaning very rarely.","items":[{"t":"rarely","pos":"adv","ex":"I rarely watch television."},{"t":"seldom","pos":"adv","ex":"He seldom eats meat."},{"t":"hardly ever","pos":"phrase","ex":"We hardly ever go to the cinema."},{"t":"once in a blue moon","pos":"idiom","ex":"I only eat fast food once in a blue moon."}]},{"id":"sp-big","cat":"speaking","grp":"big","topic":"Describing things","level":"B2","note":"All mean 'very big'. 'Vast' and 'immense' are used for size and amounts; 'massive' and 'huge' are more common in speech.","items":[{"t":"huge","pos":"adj","ex":"They live in a huge house."},{"t":"enormous","pos":"adj","ex":"The stadium is enormous."},{"t":"massive","pos":"adj","ex":"There was a massive crowd."},{"t":"vast","pos":"adj","ex":"Siberia is a vast region."}]},{"id":"sp-small","cat":"speaking","grp":"small","topic":"Describing things","level":"B2","note":"All mean 'very small'. 'Minuscule' is very small; 'miniature' describes a small copy of something.","items":[{"t":"tiny","pos":"adj","ex":"Our flat is tiny."},{"t":"minute","pos":"adj","ex":"Only a minute amount of the drug is needed."},{"t":"minuscule","pos":"adj","ex":"The difference in price is minuscule."},{"t":"miniature","pos":"adj","ex":"She collects miniature books."}]},{"id":"sp-fast","cat":"speaking","grp":"fast","topic":"Describing things","level":"B2","note":"All mean 'quick'. 'Swift' and 'prompt' are used for actions and replies; 'rapid' for change and growth.","items":[{"t":"rapid","pos":"adj","ex":"The city has seen rapid growth."},{"t":"swift","pos":"adj","ex":"The company took swift action."},{"t":"speedy","pos":"adj","ex":"We wish you a speedy recovery."},{"t":"prompt","pos":"adj","ex":"Thank you for your prompt reply."}]},{"id":"sp-slow","cat":"speaking","grp":"slow","topic":"Describing things","level":"B2","note":"All describe something not fast. 'Sluggish' suggests lack of energy; 'leisurely' is relaxed and pleasant.","items":[{"t":"sluggish","pos":"adj","ex":"The economy has been sluggish this year."},{"t":"leisurely","pos":"adj","ex":"We took a leisurely walk by the river."},{"t":"unhurried","pos":"adj","ex":"He gave an unhurried answer."},{"t":"slow-moving","pos":"adj","ex":"The slow-moving traffic made us late."}]},{"id":"sp-difficult","cat":"speaking","grp":"hard","topic":"Describing things","level":"B2","note":"All mean 'not easy'. 'Demanding' means it needs a lot of effort; 'arduous' is a long, tiring effort; 'tricky' is informal.","items":[{"t":"challenging","pos":"adj","ex":"Learning Chinese is challenging."},{"t":"demanding","pos":"adj","ex":"Being a doctor is a demanding job."},{"t":"tricky","pos":"adj","ex":"It's a tricky question."},{"t":"arduous","pos":"adj","ex":"They made the arduous journey on foot."}]},{"id":"sp-easy","cat":"speaking","grp":"easy","topic":"Describing things","level":"B2","note":"All mean 'not difficult'. 'A piece of cake' is an idiom.","items":[{"t":"straightforward","pos":"adj","ex":"The instructions are straightforward."},{"t":"effortless","pos":"adj","ex":"She makes dancing look effortless."},{"t":"a piece of cake","pos":"idiom","ex":"The test was a piece of cake."},{"t":"undemanding","pos":"adj","ex":"It's an undemanding job."}]},{"id":"sp-clever","cat":"speaking","grp":"smart","topic":"People","level":"B2","note":"All mean 'intelligent'. 'Brainy' is informal.","items":[{"t":"intelligent","pos":"adj","ex":"She is an intelligent and curious student."},{"t":"sharp","pos":"adj","ex":"He's got a sharp mind."},{"t":"smart","pos":"adj","ex":"That was a smart decision."},{"t":"brainy","pos":"adj","ex":"My brainy cousin always wins quizzes."}]},{"id":"sp-friendly","cat":"speaking","grp":"friendly","topic":"People","level":"B2","note":"All describe people who are easy to get on with. 'Approachable' means easy to talk to.","items":[{"t":"sociable","pos":"adj","ex":"He is a sociable person who loves parties."},{"t":"outgoing","pos":"adj","ex":"She's outgoing and makes friends easily."},{"t":"approachable","pos":"adj","ex":"Our manager is very approachable."},{"t":"amiable","pos":"adj","ex":"The hotel owner was amiable and helpful."}]},{"id":"sp-rude","cat":"speaking","grp":"rude","topic":"People","level":"B2","note":"All describe bad manners. 'Discourteous' is formal.","items":[{"t":"rude","pos":"adj","ex":"It's rude to interrupt people."},{"t":"impolite","pos":"adj","ex":"It is impolite to arrive late."},{"t":"disrespectful","pos":"adj","ex":"Some teenagers are disrespectful to teachers."},{"t":"ill-mannered","pos":"adj","ex":"He was an ill-mannered guest."}]},{"id":"sp-honest","cat":"speaking","grp":"honest","topic":"People","level":"B2","note":"All describe telling the truth. 'Frank' and 'candid' mean honest in a direct way, even if it is uncomfortable.","items":[{"t":"honest","pos":"adj","ex":"She is honest about her mistakes."},{"t":"truthful","pos":"adj","ex":"He gave a truthful answer."},{"t":"frank","pos":"adj","ex":"Let me be frank with you."},{"t":"candid","pos":"adj","ex":"The manager was candid about the problems."}]},{"id":"sp-tasty","cat":"speaking","grp":"tasty","topic":"Food","level":"B2","note":"All mean 'tastes very good'. 'Mouth-watering' makes you want to eat it immediately.","items":[{"t":"delicious","pos":"adj","ex":"The soup was absolutely delicious."},{"t":"mouth-watering","pos":"adj","ex":"The smell of fresh bread was mouth-watering."},{"t":"tasty","pos":"adj","ex":"It's a simple but tasty meal."},{"t":"scrumptious","pos":"adj","ex":"We had a scrumptious dessert."}]},{"id":"sp-hungry","cat":"speaking","grp":"hungry","topic":"Food","level":"B2","note":"All mean 'very hungry'. 'I could eat a horse' is a humorous idiom.","items":[{"t":"starving","pos":"adj","ex":"I'm starving; let's eat."},{"t":"famished","pos":"adj","ex":"After the hike we were famished."},{"t":"ravenous","pos":"adj","ex":"The children were ravenous after swimming."},{"t":"I could eat a horse","pos":"idiom","ex":"I haven't eaten all day; I could eat a horse!"}]},{"id":"sp-noisy","cat":"speaking","grp":"noisy","topic":"Places","level":"B2","note":"All mean 'making a lot of noise'. 'Deafening' and 'ear-splitting' are extremely loud.","items":[{"t":"noisy","pos":"adj","ex":"The street is noisy at night."},{"t":"loud","pos":"adj","ex":"The music was too loud."},{"t":"deafening","pos":"adj","ex":"The crowd's cheering was deafening."},{"t":"ear-splitting","pos":"adj","ex":"There was an ear-splitting scream."}]},{"id":"sp-beautiful","cat":"speaking","grp":"beautiful","topic":"Places","level":"B2","note":"All mean 'very beautiful'. 'Picturesque' describes places that look like a picture; 'breathtaking' means amazing.","items":[{"t":"stunning","pos":"adj","ex":"The mountain view was stunning."},{"t":"gorgeous","pos":"adj","ex":"It's a gorgeous beach."},{"t":"breathtaking","pos":"adj","ex":"The sunrise was breathtaking."},{"t":"picturesque","pos":"adj","ex":"We stayed in a picturesque village."}]},{"id":"sp-calm","cat":"speaking","grp":"calm","topic":"Places","level":"B2","note":"All mean 'quiet and relaxing'. 'Serene' and 'tranquil' are more poetic.","items":[{"t":"peaceful","pos":"adj","ex":"The lake is a peaceful place to read."},{"t":"tranquil","pos":"adj","ex":"They live in a tranquil village."},{"t":"serene","pos":"adj","ex":"The garden was serene in the early morning."},{"t":"calm","pos":"adj","ex":"I prefer a calm evening at home."}]},{"id":"sp-cold","cat":"speaking","grp":"cold","topic":"Weather","level":"B2","note":"All describe very cold weather. 'Chilly' is mildly cold; 'freezing' and 'icy' are very cold.","items":[{"t":"freezing","pos":"adj","ex":"It was freezing this morning."},{"t":"chilly","pos":"adj","ex":"It gets chilly in the evenings."},{"t":"icy","pos":"adj","ex":"An icy wind blew all day."},{"t":"bitterly cold","pos":"phrase","ex":"It was bitterly cold in January."}]},{"id":"sp-hot","cat":"speaking","grp":"hot","topic":"Weather","level":"B2","note":"All describe very hot weather. 'Sweltering' means unpleasantly hot and humid; 'scorching' means extremely hot sun.","items":[{"t":"boiling","pos":"adj","ex":"It's boiling in here; open a window."},{"t":"scorching","pos":"adj","ex":"It was a scorching summer day."},{"t":"sweltering","pos":"adj","ex":"The city is sweltering in the heat wave."},{"t":"baking","pos":"adj","ex":"It's baking outside today."}]},{"id":"sp-think","cat":"speaking","grp":"think","topic":"Thinking","level":"B2","note":"All mean 'think carefully'. 'Mull over' is informal; 'ponder' and 'reflect on' are more formal.","items":[{"t":"consider","pos":"verb","ex":"I'm considering studying abroad.","k":"considering"},{"t":"ponder","pos":"verb","ex":"She pondered the question for a moment.","k":"pondered"},{"t":"reflect on","pos":"phrase","ex":"It helps to reflect on your mistakes.","k":"reflect on"},{"t":"mull over","pos":"phrase","ex":"I need time to mull it over.","k":"mull it over"}]},{"id":"sp-very","cat":"speaking","grp":"very","topic":"Intensifiers","level":"B2","note":"All mean 'very'. Use them with adjectives that can be 'gradable' (extremely tired, incredibly helpful). Do not use them with adjectives that are already extreme (not 'extremely freezing').","items":[{"t":"extremely","pos":"adv","ex":"The exam was extremely difficult."},{"t":"incredibly","pos":"adv","ex":"The staff were incredibly helpful."},{"t":"exceptionally","pos":"adv","ex":"She is an exceptionally talented dancer."},{"t":"immensely","pos":"adv","ex":"I enjoyed the concert immensely."}]}];
